let VA=null,VEl=null,VRate=1;
function vpUpd(){if(!VEl||!VA)return;const d=VA.duration&&isFinite(VA.duration)?VA.duration:(+VEl.dataset.d||0);const p=d?Math.min(1,VA.currentTime/d):0;VEl.querySelector(".vpf").style.width=(p*100)+"%";VEl.querySelector(".vpk").style.insetInlineStart="calc("+(p*100)+"% - 6px)";VEl.querySelector(".vpd").textContent=mmss(VA.paused&&!VA.currentTime?d:VA.currentTime)}
