async function sendFile(b,type,name,cap){if(b.size>5*1024*1024){toast(T("צו גרויס (מאקס 5MB)"));return}const u=await upload(b,type,name);if(!u)return;const rt=replyTo;setReply(null);await api({a:"send",conv,body:cap,file_key:u.key,file_type:u.type,file_name:name,reply_to:rt});load()}
