function fileHtml(m){if(!m.file_key)return"";const t=m.file_type||"",u="/f/"+m.file_key;if(t.startsWith("audio")){const d=+(String(m.file_name||"").split("|")[1]||0);return'<div class="vp" data-src="'+u+'" data-d="'+d+'"><button type="button" class="vpb">▶</button><div class="vpt"><div class="vpf"></div><span class="vpk"></span></div><span class="vpd">'+mmss(d)+'</span><button type="button" class="vps">1×</button></div>'}if(t.startsWith("image"))return'<img class="ph" loading="lazy" src="'+u+'" alt="">';if(t.startsWith("video"))return'<video controls preload="metadata" playsinline src="'+u+'#t=0.1"></video>';
const ic=/pdf/.test(t)?"📕":/word|doc/.test(t)?"📘":/sheet|excel/.test(t)?"📗":/zip/.test(t)?"🗜️":"📄";return'<a class="doc" href="'+u+'?dl=1" target="_blank" rel="noopener"><span class="ic">'+ic+'</span><span>'+esc(m.file_name||T("פייל"))+'</span></a>'}
function pollHtml(m){const p=m.poll;if(!p)return"";const tot=p.counts.reduce((a,b)=>a+b,0)||0;return'<div class="poll"><div class="pq">📊 '+esc(p.q)+'</div>'+p.opts.map((o,i)=>{const pc=tot?Math.round(p.counts[i]*100/tot):0;return'<button type="button" class="po'+(p.my===i?" my":"")+'" data-v="'+i+'"><span class="fill" style="width:'+pc+'%"></span><span>'+(p.my===i?"✔ ":"")+esc(o)+'</span><span class="c">'+p.counts[i]+'</span></button>'}).join("")+'<div class="small muted">'+tot+T(' שטימען</div></div>')}
