let q="";if(m.reply_to){const o=M.get(m.reply_to);q='<div class="q" data-go="'+m.reply_to+'"><b>'+esc(o?o.name:"")+'</b>'+esc(o?prevTxt(o).slice(0,90):"…")+'</div>'}
