j.msgs.forEach(m=>{const isNew=!M.has(m.id);put(m);since=Math.max(since,m.updated);if(isNew&&!first&&!m.mine&&!m.deleted){beep();if(m.id>lastNotified){lastNotified=m.id;S.setItem("chatLastN",m.id);notify(m.name,prevTxt(m),conv)}}});
