const stp=e.target.closest("[data-stop]");if(stp){api({a:"locstop",conv,id:+stp.dataset.stop}).then(load);return}
{const el0=e.target.closest(".msg");if(el0&&!SEL.size&&!e.target.closest("a,button,audio,video,.vp,.po")){const id=+el0.dataset.id,t=Date.now();if(lastTap.id===id&&t-lastTap.t<350){lastTap={id:0,t:0};dblLike(id);return}lastTap={id,t}}}
